70	<script>
71	  var STORAGE_KEY = 'todos';
72	
73	  function makeId() {
74	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
75	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
76	  }
77	
78	  function load() {
79	    try {
80	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
81	      return Array.isArray(data) ? data : [];
82	    } catch (e) {
83	      return [];
84	    }
85	  }
86	
87	  function save(todos) {
88	    try {
89	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
90	    } catch (e) {}
91	  }
92	
93	  var todos = load();
94	  var form = document.getElementById('todo-form');
95	  var input = form.querySelector('[data-testid="todo-input"]');
96	  var list = document.getElementById('todo-list');
97	  var empty = document.getElementById('empty');
98	
