102	      var li = document.createElement('li');
103	      li.setAttribute('data-testid', 'todo-item');
104	      li.dataset.id = todo.id;
105	
106	      var text = document.createElement('span');
107	      text.className = 'text';
108	      text.setAttribute('data-testid', 'todo-text');
109	      text.textContent = todo.text;
110	
111	      var del = document.createElement('button');
112	      del.type = 'button';
113	      del.className = 'delete';
114	      del.setAttribute('data-testid', 'todo-delete');
115	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
116	      del.textContent = 'Delete';
117	      del.addEventListener('click', function () {
118	        todos = todos.filter(function (t) { return t.id !== todo.id; });
